import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer.optimize(FUNC, GoalType, double, double)
 */
public class MultiStartUnivariateRealOptimizer_optimize_TriageGen2Test {

    private BaseUnivariateRealOptimizer<UnivariateRealFunction> mockOptimizer;
    private MultiStartUnivariateRealOptimizer optimizer;
    private UnivariateRealFunction function;

    @Before
    public void setUp() {
        mockOptimizer = mock(BaseUnivariateRealOptimizer.class);
        // Using 1 start to simplify testing the delegation
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 1, new JDKRandomGenerator());
        function = x -> x * x;
    }

    @Test
    public void testOptimize_Success() throws FunctionEvaluationException {
        // Arrange
        double min = -10.0;
        double max = 10.0;
        double expectedStartValue = min + 0.5 * (max + min); // 0.0
        GoalType goal = GoalType.MINIMIZE;

        UnivariateRealPointValuePair expectedResult = new AbstractUnivariateRealPointValuePair(0.0, 0.0);

        when(mockOptimizer.optimize(any(UnivariateRealFunction.class), any(GoalType.class), any(double.class), any(double.class), any(double.class)))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(0.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);

        // Verify that the 5-parameter version was called with the calculated midpoint
        org.mockito.Mockito.verify(mockOptimizer).optimize(function, goal, min, max, expectedStartValue);
    }

    @Test
    public void testOptimize_ThrowsFunctionEvaluationException() throws FunctionEvaluationException {
        // Arrange
        double min = -10.0;
        double max = 10.0;
        GoalType goal = GoalType.MAXIMIZE;

        when(mockOptimizer.optimize(any(UnivariateRealFunction.class), any(GoalType.class), any(double.class), any(double.class), any(double.class)))
            .thenThrow(new FunctionEvaluationException(new RuntimeException("Evaluation failed")));

        // Act & Assert
        try {
            optimizer.optimize(function, goal, min, max);
            org.junit.Assert.fail("Expected FunctionEvaluationException to be thrown");
        } catch (FunctionEvaluationException e) {
            // Expected
        }
    }

    /**
     * Helper class to mock the return type if AbstractUnivariateRealPointValuePair is not easily accessible
     */
    private static class AbstractUnivariateRealPointValuePair implements UnivariateRealPointValuePair {
        private final double point;
        private final double value;

        public AbstractUnivariateRealPointValuePair(double point, double value) {
            this.point = point;
            this.value = value;
        }

        @Override
        public double getPoint() { return point; }

        @Override
        public double getValue() { return value; }
    }
}
